import java.util.concurrent.CountDownLatch

fun main() {
    val acc = CustodyAccumulator()
    val start = CountDownLatch(1)
    val workers = (0 until 8).map { tid ->
        Thread {
            start.await()
            for (i in 0 until 150) {
                acc.record("t$tid-$i", 1L)
            }
        }
    }
    workers.forEach { it.start() }
    start.countDown()
    workers.forEach { it.join() }
    assert(acc.totalBalance() == 1200L) { "Expected 1200, got ${acc.totalBalance()}" }
    assert(acc.entryCount() == 1200) { "Expected 1200 entries, got ${acc.entryCount()}" }
    println("ALL TESTS PASSED")
}

